values ($lx$qi-zhang-md-glendale$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Qi Zhang, MD, FACOG (Desert West OB/GYN)$lx$, null, $lx$Board-certified OB/GYN at Desert West OB/GYN in Glendale who speaks English and Mandarin.$lx$, $lx$格倫代爾 Desert West OB/GYN 的婦產科專科醫師，可說英語及國語。$lx$, $lx$Dr. Qi Zhang is a board-certified obstetrician and gynecologist with Desert West OB/GYN, whose main office is at 6678 W Thunderbird Rd in Glendale; the practice also has offices in Peoria and north Phoenix and books appointments at (602) 978-1500. Dr. Zhang earned an undergraduate degree at Arizona State University and a medical degree at the University of Arizona, completed an obstetrics and gynecology residency at the University of Texas in 2007 and then joined Desert West. Dr. Zhang speaks English and Mandarin. Languages as listed on Desert West OB/GYN's provider page, checked November 2026.$lx$, $lx$Qi Zhang 醫師是婦產科專科醫師，任職於 Desert West OB/GYN，診所總部位於格倫代爾（Glendale）6678 W Thunderbird Rd，另在皮奧里亞及鳳凰城北部設有診所，預約電話 (602) 978-1500。Zhang 醫師在亞利桑那州立大學取得學士學位、亞利桑那大學取得醫學博士學位，2007 年在德州大學完成婦產科住院醫師訓練後加入 Desert West。能說英語及國語。語言資訊依據 Desert West OB/GYN 醫師頁面，2026 年 11 月查核。$lx$, $lx$Glendale$lx$, $lx$Greater Phoenix$lx$, $lx$6678 W Thunderbird Rd, Glendale, AZ 85306$lx$, null, $lx$(602) 978-1500$lx$, null, $lx$https://desertwestobgyn.com/providers/qi-zhang-md-facog$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Qi Zhang, MD, FACOG (Desert West OB/GYN)$lx$, $lx$Glendale$lx$, $lx$medical$lx$, $lx$desertwestobgyn.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

