values ($lx$jinmeng-zhang-md-peoria$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Jinmeng Zhang, MD, FAAD (U.S. Dermatology Partners)$lx$, null, $lx$Mandarin-speaking board-certified dermatologist in Peoria, accepting new patients.$lx$, $lx$皮奧里亞會說國語的皮膚科專科醫師，目前接受新病患。$lx$, $lx$Dr. Jinmeng Zhang is a board-certified dermatologist and Fellow of the American Academy of Dermatology with U.S. Dermatology Partners, seeing patients at its Peoria clinic at 13943 N 91st Ave, #C-101, and is accepting new patients. Dr. Zhang earned a medical degree at Wayne State University School of Medicine, completed an internship at St. John Hospital & Medical Center and a dermatology residency at Washington University in St. Louis, where Dr. Zhang was chief resident. The page lists Mandarin Chinese as an additional language. Languages as listed on U.S. Dermatology Partners' provider page, checked November 2026.$lx$, $lx$Jinmeng Zhang 醫師是皮膚科專科醫師，也是美國皮膚科醫學會院士（FAAD），任職於 U.S. Dermatology Partners，在皮奧里亞（Peoria）13943 N 91st Ave, #C-101 的診所看診，目前接受新病患。Zhang 醫師畢業於韋恩州立大學醫學院，在 St. John Hospital & Medical Center 完成實習，並在聖路易華盛頓大學完成皮膚科住院醫師訓練，曾任總住院醫師。頁面列出的其他語言為國語。語言資訊依據 U.S. Dermatology Partners 醫師頁面，2026 年 11 月查核。$lx$, $lx$Peoria$lx$, $lx$Greater Phoenix$lx$, $lx$13943 N 91st Ave, #C-101, Peoria, AZ 85381$lx$, null, $lx$(623) 972-3992$lx$, null, $lx$https://www.usdermatologypartners.com/provider/jinmeng-zhang-md/$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Jinmeng Zhang, MD, FAAD (U.S. Dermatology Partners)$lx$, $lx$Peoria$lx$, $lx$medical$lx$, $lx$usdermatologypartners.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
