values ($lx$alfredo-lim-md-phoenix$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Alfredo Lim, MD (HonorHealth)$lx$, null, $lx$Cantonese-speaking internal medicine doctor with HonorHealth in north-central Phoenix.$lx$, $lx$鳳凰城中北部 HonorHealth 會說粵語的內科醫師。$lx$, $lx$Dr. Alfredo Lim is an internal medicine physician with HonorHealth at 9250 N 3rd St, Suite 4010, in north-central Phoenix. HonorHealth lists the languages as English, Filipino and Chinese - Cantonese, so patients can see an adult primary care doctor in Cantonese. The office phone, (602) 997-7331, is the same on the HonorHealth profile and in the federal NPI registry. Languages as listed on HonorHealth's Find a Doctor directory, checked November 2026.$lx$, $lx$Alfredo Lim 醫師是 HonorHealth 的內科醫師，在鳳凰城中北部 9250 N 3rd St, Suite 4010 看診。HonorHealth 列出的語言為英語、菲律賓語及粵語，可用粵語看成人基層醫療門診。診所電話 (602) 997-7331，HonorHealth 醫師頁面與聯邦 NPI 登記資料相同。語言資訊依據 HonorHealth「Find a Doctor」醫師名錄，2026 年 11 月查核。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$9250 N 3rd St, Suite 4010, Phoenix, AZ$lx$, null, $lx$(602) 997-7331$lx$, null, $lx$https://www.honorhealth.com/physicians/alfredo-lim$lx$, array[$lx$English$lx$, $lx$Cantonese$lx$]::text[], array[$lx$Alfredo Lim, MD (HonorHealth)$lx$, $lx$Phoenix$lx$, $lx$medical$lx$, $lx$honorhealth.com$lx$, $lx$English$lx$, $lx$Cantonese$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
