insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$da-wei-liao-md-phoenix$lx$, (select id from public.business_categories where slug = $lx$medical$lx$), $lx$Da-Wei Liao, MD$lx$, null, $lx$Mandarin-speaking pulmonary and critical care physician in north Phoenix.$lx$, $lx$鳳凰城北部會說國語的胸腔內科及重症醫學醫師。$lx$, $lx$Dr. Da-Wei Liao is a pulmonary and critical care physician with an office at 3811 E Bell Rd, Suite 107, in north Phoenix, and a member of the HonorHealth medical staff. HonorHealth lists board certifications from the American Board of Internal Medicine in critical care medicine and pulmonary disease, and languages of Chinese, Chinese - Mandarin and English. The office address and phone, (602) 340-1689, come from the federal NPI registry (updated October 2025), and the phone matches the HonorHealth profile. Languages as listed on HonorHealth's Find a Doctor directory, checked November 2026.$lx$, $lx$Da-Wei Liao 醫師是胸腔內科及重症醫學醫師，診所位於鳳凰城北部 3811 E Bell Rd, Suite 107，也是 HonorHealth 醫療團隊成員。HonorHealth 列出其持有美國內科醫學委員會的重症醫學及胸腔疾病專科認證，語言為中文、國語及英語。診所地址與電話 (602) 340-1689 依據聯邦 NPI 登記資料（2025 年 10 月更新），電話與 HonorHealth 頁面相同。語言資訊依據 HonorHealth「Find a Doctor」醫師名錄，2026 年 11 月查核。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$3811 E Bell Rd, Suite 107, Phoenix, AZ 85032$lx$, null, $lx$(602) 340-1689$lx$, null, $lx$https://www.honorhealth.com/physicians/da-wei-liao$lx$, array[$lx$English$lx$, $lx$Mandarin$lx$]::text[], array[$lx$Da-Wei Liao, MD$lx$, $lx$Phoenix$lx$, $lx$medical$lx$, $lx$honorhealth.com$lx$, $lx$English$lx$, $lx$Mandarin$lx$, $lx$doctor physician$lx$, $lx$醫師 看診$lx$, $lx$Chinese-speaking$lx$, $lx$中文服務$lx$]::text[], true, true, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
